enhanced_schema:
{
  "tables": [
    {
      "table_name": "courses",
      "columns": [
        {
          "name": "course_id",
          "type": "INTEGER",
          "description": "Unique identifier for each course"
        },
        {
          "name": "course_code",
          "type": "VARCHAR",
          "description": "Course code as used in the university catalog"
        },
        {
          "name": "title",
          "type": "VARCHAR",
          "description": "Title of the course"
        },
        {
          "name": "credits",
          "type": "INTEGER",
          "description": "Number of credits the course is worth"
        },
        {
          "name": "description",
          "type": "TEXT",
          "description": "Brief overview of the course"
        },
        {
          "name": "department_id",
          "type": "INTEGER",
          "description": "ID of the department offering the course"
        },
        {
          "name": "prerequisite_course_id",
          "type": "INTEGER",
          "description": "ID of the prerequisite course"
        },
        {
          "name": "is_active",
          "type": "BOOLEAN",
          "description": "Indicates if the course is active"
        }
      ],
      "primary_key": [
        "course_id"
      ]
    },
    {
