        {
          "name": "year",
          "type": "INTEGER",
          "description": "Year of the semester"
        },
        {
          "name": "start_date",
          "type": "DATE",
          "description": "Start date of the semester"
        },
        {
          "name": "end_date",
          "type": "DATE",
          "description": "End date of the semester"
        }
