        },
        {
          "name": "capacity",
          "type": "INTEGER",
          "description": "Maximum number of students allowed"
        },
        {
          "name": "enrolled_students",
          "type": "INTEGER",
          "description": "Current number of enrolled students"
        },
        {
          "name": "room_id",
          "type": "INTEGER",
          "description": "ID of the room where the course is held"
        }
      ],
      "primary_key": [
        "offering_id"
      ]
    },
    {
